CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Each thread computes one output voxel [n, c, d_out, h_out, w_out].
// Uses float2 vectorized loads for the two contiguous W-axis elements at each
// of the four (d,h) corners of the 2x2x2 pool window.
// Assumes the input tensor is contiguous float32 in NCDHW layout.
__global__ void fused_epilogue_kernel(
    const float* __restrict__ inp,   // conv output [N, C, D, H, W]
    const float* __restrict__ bias,  // [C] (bias_shape is [C,1,1,1])
    float* __restrict__ out,         // [N, C, D/2, H/2, W/2]
    float pool_scale,                // scale1 * 0.125f
    float out_scale,                 // scale2
    int N, int C,
    int D, int H, int W,             // input spatial dims
    int D2, int H2, int W2           // output spatial dims = D/2, H/2, W/2
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * D2 * H2 * W2;
    if (idx >= total) return;

    // Decode linear index -> (n, c, d2, h2, w2)
    int w2 = idx % W2; int tmp = idx / W2;
    int h2 = tmp % H2; tmp /= H2;
    int d2 = tmp % D2; tmp /= D2;
    int c  = tmp % C;
    int n  = tmp / C;

    // Strides for NCDHW layout
    int sN = C * D * H * W;
    int sC = D * H * W;
    int sD = H * W;
    // stride over H axis == W

    // Base offset at (n, c, d2*2, h2*2, w2*2)
    // w2*2 must be even-aligned for float2; w2 indexes pairs so w2*2 is always even.
    int base = n * sN + c * sC + d2 * 2 * sD + h2 * 2 * W + w2 * 2;

    // Load four float2 values (one per (d,h) corner) covering the 2x2x2 window.
    // Each float2 spans (w2*2, w2*2+1) â the contiguous width pair.
    float2 v00 = *reinterpret_cast<const float2*>(inp + base);              // d0, h0
    float2 v01 = *reinterpret_cast<const float2*>(inp + base + W);          // d0, h1
    float2 v10 = *reinterpret_cast<const float2*>(inp + base + sD);         // d1, h0
    float2 v11 = *reinterpret_cast<const float2*>(inp + base + sD + W);     // d1, h1

    float sum = (v00.x + v00.y) + (v01.x + v01.y) + (v10.x + v10.y) + (v11.x + v11.y);

    // Formula: ((sum * scale1 / 8) + bias[c]) * scale2
    out[idx] = (sum * pool_scale + bias[c]) * out_scale;
}

